        LocalDate date = LocalDate.of(2023, 1, 1);
        double deltaT = DeltaT.estimate(date);
        assertTrue(deltaT > 0 && deltaT < 30);
    }

    @Test
    public void estimate_validDate_TodaySameAsInput_ReturnsZero() {
